function checkPrimeNumbers(numbers) {
  // Check input: array of 5 numbers
  if (!Array.isArray(numbers) || numbers.length !== 5) {
    console.error("Input must be an array of 5 numbers.");
    return;
  }

  // Loop through array and check each number for primality
  for (let I = 0; I < numbers.length; i++) {
    const number = numbers[i];

    // Check if number is a valid integer
    if (!Number.isInteger(number)) {
      console.error(`Element at index ${i} is not a valid integer.`);
      return;
    }

    // Check if number is prime
    if (isPrime(number)) {
      console.log(`Element at index ${i} is a prime number: ${number}`);
      return;
    }
  }
}

// Helper function to check if a number is prime
function isPrime(n) {
  if (n <= 1) return false;
  for (let I = 2; I * I <= n; i++) {
    if (n % I === 0) return false;
  }
  return true;
}

// Example usage
