Here's an example C++ program that reads a text file line by line and counts the number of occurrences of a specific word:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int countWordOccurrences(string filename, string word) {
    int count = 0;
    string line;

    ifstream file(filename);
    if (file.is_open()) {
        while (getline(file, line)) {
            // convert line to lowercase for case-insensitive matching
            transform(line.begin(), line.end(), line.begin(), ::tolower);

            // count occurrences of the word in the line
            size_t pos = line.find(word);
            while (pos != string::npos) {
                count++;
                pos = line.find(word, pos + 1);
            }
        }
        file.close();
    } else {
        cout << "Unable to open file: " << filename << endl;
    }

    return count;
}

int main() {
    string filename = "input.txt";
    string word = "example";

    int occurrences = countWordOccurrences(filename, word);
    cout << "Number of occurrences of \"" << word << "\" in " << filename << ": " << occurrences << endl;

    return 0;
}
```

To use this program, replace `input.txt` and `example` with the name of your input file and the word you want to count, respectively. The program assumes that the input file is in the same directory as the executable.

The `countWordOccurrences` function takes the filename and word as input and returns the number of occurrences. The `main` function calls this function and prints the result. The function first opens the file and reads it line by line, converting each line to lowercase for case-insensitive matching. It then searches for the word in each line and updates the count accordingly. If the file cannot be opened, an error message is printed.
